CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK (role IN ('admin','guru')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.tka_has_role(wanted text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND (role = wanted OR role = 'admin')) $$;
REVOKE ALL ON FUNCTION public.tka_has_role(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tka_has_role(text) TO anon, authenticated, service_role;
CREATE TABLE public.app_kv (key text PRIMARY KEY, data jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.app_kv TO anon;
GRANT SELECT, INSERT, UPDATE ON public.app_kv TO authenticated;
GRANT ALL ON public.app_kv TO service_role;
ALTER TABLE public.app_kv ENABLE ROW LEVEL SECURITY;
CREATE POLICY "kv read" ON public.app_kv FOR SELECT TO anon, authenticated USING (key IN ('tka_question_bank','tka_exam_classes'));
CREATE POLICY "kv insert" ON public.app_kv FOR INSERT TO authenticated WITH CHECK ((key = 'tka_question_bank' AND public.tka_has_role('admin')) OR (key = 'tka_exam_classes' AND public.tka_has_role('guru')));
CREATE POLICY "kv update" ON public.app_kv FOR UPDATE TO authenticated USING ((key = 'tka_question_bank' AND public.tka_has_role('admin')) OR (key = 'tka_exam_classes' AND public.tka_has_role('guru'))) WITH CHECK ((key = 'tka_question_bank' AND public.tka_has_role('admin')) OR (key = 'tka_exam_classes' AND public.tka_has_role('guru')));
CREATE TABLE public.exam_results (id text PRIMARY KEY, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.exam_results TO anon;
GRANT SELECT, INSERT, DELETE ON public.exam_results TO authenticated;
GRANT ALL ON public.exam_results TO service_role;
ALTER TABLE public.exam_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY "results read" ON public.exam_results FOR SELECT TO authenticated USING (public.tka_has_role('guru'));
CREATE POLICY "results insert" ON public.exam_results FOR INSERT TO anon, authenticated WITH CHECK (jsonb_typeof(data) = 'object' AND data->>'id' = id AND length(data->>'studentName') BETWEEN 1 AND 200 AND EXISTS (SELECT 1 FROM public.app_kv k, jsonb_array_elements(k.data) e WHERE k.key = 'tka_exam_classes' AND e->>'id' = exam_results.data->>'examId' AND e->>'status' = 'OPEN'));
CREATE POLICY "results delete" ON public.exam_results FOR DELETE TO authenticated USING (public.tka_has_role('admin'));